import{_ as l,c as t,b as s,o as r}from"./app-DKvarYBr.js";const a={};function n(o,e){return r(),t("div",null,e[0]||(e[0]=[s('<p>Till now you must have switched to the new theme, or some of you have just installed the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace App</a> and want to have the &quot;Seller Membership&quot; feature app, then do refer to this.</p><p>This feature app allows the Admin/Store Owner to make plans for the Sellers and they need to subscribe to the plan in case they need to publish the products in the Admin Shopify Store.</p><h3 id="features" tabindex="-1"><a class="header-anchor" href="#features"><span>Features</span></a></h3><ul><li>Admin can make membership plans for the Sellers.</li><li>Sellers can subscribe to the plan to publish their products to the admin&#39;s store.</li><li>Being an admin, You can enable or disable the membership for the sellers.</li><li>If disabled, Your sellers will log in directly to their respective seller panels without having a membership.</li><li>Admin can allow sellers to deactivate their membership plan if required.</li><li>He can also set a one-time Setup fee for Sellers for the Plans he creates.</li></ul><p>Admin will set the payment methods through which he/she wants the payment from sellers. You can activate any of the payment methods of your choice from the <strong>Payment Details</strong> section.</p><p>The featured app is a monthly costing of <strong>$25 USD</strong> per month apart from the Multivendor App.</p><p>Check the below video of Seller Membership:</p><hr><h3 id="activation" tabindex="-1"><a class="header-anchor" href="#activation"><span>Activation</span></a></h3><p>You need to enable the App from here:</p><p><strong>Go to Admin Panel → Feature App section → Enable the feature → Save Changes.</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/29081836/AwesomeScreenshot-Feature-Apps-Admin-2019-07-29-13-07-60.png" alt="seller membership"></p><p>Once you enable the featured app, you need to approve the charges for the app i.e. <strong>$25 USD/month</strong>.</p><hr><h3 id="admin-end" tabindex="-1"><a class="header-anchor" href="#admin-end"><span>Admin End</span></a></h3><p>Once the App is activated, Admin will configure the same from the <strong>Configuration → Membership Configuration</strong> menu:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Membership-Configuration-Admin-1.png" alt="seller membership"></p><ul><li><strong>Display Membership Plan to Seller</strong> – Choose if sellers should pick a plan during or after signup.</li><li><strong>If Seller Payment is Due</strong> – Choose what happens if a seller misses payment: block access, disable products, etc.</li><li><strong>Apply Updated Plan Changes</strong> – Choose whether updated plans apply to all or only new sellers.</li><li><strong>Enable Membership for Sellers</strong> – Toggle to enable/disable the membership requirement.</li><li><strong>Allow Seller to Deactivate Membership</strong> – Let sellers cancel membership if needed.</li><li><strong>Provide Plan Link on Seller Dashboard Header</strong> – Show a &quot;Plan&quot; link on the seller panel header.</li></ul><hr><h3 id="accept-card-details-before-trial-period" tabindex="-1"><a class="header-anchor" href="#accept-card-details-before-trial-period"><span>Accept Card Details Before Trial Period</span></a></h3><p>Go to <strong>Multi-vendor Admin Panel → Configuration → Membership Configuration</strong>, then enable the tab.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-4-1200x549.png" alt="Screenshot-4"></p><hr><h3 id="create-new-plans" tabindex="-1"><a class="header-anchor" href="#create-new-plans"><span>Create New Plans</span></a></h3><p><strong>Go to Sellers → Seller Membership Plans</strong> in the app.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Membership-Plans-Admin-3.png" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Membership-Plans-Admin-3.png" alt="seller membership"></a></p><h4 id="create-membership-plans-for-the-seller" tabindex="-1"><a class="header-anchor" href="#create-membership-plans-for-the-seller"><span>Create Membership Plans for the Seller:</span></a></h4><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Add-Membership-Plan-Admin.png" alt="seller membership"></p><p>While creating a plan:</p><ul><li>Enter name, price, billing cycle (monthly/yearly).</li><li>Choose product limit (unlimited or fixed count).</li><li>Set due date, grace period.</li></ul><hr><h3 id="set-commission-on-membership-plans" tabindex="-1"><a class="header-anchor" href="#set-commission-on-membership-plans"><span>Set Commission on Membership Plans</span></a></h3><p>While creating a plan, enable <strong>Set Commission by Membership Plan</strong> and enter a percentage.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Add-Membership-Plan-Admin-1.png" alt="Add Membership Plan Admin"></p><blockquote><p>Commission Priority: Membership &gt; Product-wise &gt; Category-wise &gt; Seller-wise &gt; Global</p></blockquote><hr><h3 id="restrict-sellers-to-add-staff-in-membership-plan" tabindex="-1"><a class="header-anchor" href="#restrict-sellers-to-add-staff-in-membership-plan"><span>Restrict Sellers to Add Staff in Membership Plan</span></a></h3><p>If using the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-app-seller-staff/" target="_blank" rel="noopener noreferrer">Seller Staff App</a>, restrict staff per membership plan.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Add-Membership-Plan-Admin-3.png" alt="Add Membership Plan Admin"></p><hr><h3 id="set-one-time-setup-fee-for-sellers" tabindex="-1"><a class="header-anchor" href="#set-one-time-setup-fee-for-sellers"><span>Set One-Time Setup Fee for Sellers</span></a></h3><p>Set one-time setup fee when creating plans.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Add-Membership-Plan-Admin-2.png" alt="One time setup fee"></p><p>Reorder plans via:<br><strong>Sellers → Seller Membership → REORDER PLANS</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/screenshot_from_2022_09_23_19_35_15-1200x570.png" alt="screenshot_from_2022_09_23_19_35_15"></p><hr><h3 id="assign-membership-plans-to-sellers" tabindex="-1"><a class="header-anchor" href="#assign-membership-plans-to-sellers"><span>Assign Membership Plans to Sellers</span></a></h3><h4 id="while-adding-seller" tabindex="-1"><a class="header-anchor" href="#while-adding-seller"><span>While Adding Seller:</span></a></h4><p>After filling details and clicking <strong>Save</strong>, select a plan.</p><h4 id="while-editing-seller" tabindex="-1"><a class="header-anchor" href="#while-editing-seller"><span>While Editing Seller:</span></a></h4><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Edit-Seller-Admin-1.png" alt="Membership10"></p><p>You’ll see plans appear after clicking <strong>Save Changes</strong>.</p><p>View subscribed sellers here:<br><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Seller-Memberships-Admin-.png" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Seller-Memberships-Admin-.png" alt="Membership5"></a></p><hr><h3 id="payment-from-seller" tabindex="-1"><a class="header-anchor" href="#payment-from-seller"><span>Payment from Seller</span></a></h3><p>More on this here:<br> 👉 <a href="https://webkul.com/blog/seller-membership-payment-methods-multi-vendor-marketplace-for-shopify/" target="_blank" rel="noopener noreferrer">Seller Membership Payment Methods</a></p><p><strong>Steps:</strong></p><p><strong>Go to Configuration → Payment Details</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/membership-1200x985.webp" alt="membership"></p><hr><h3 id="seller-end" tabindex="-1"><a class="header-anchor" href="#seller-end"><span>Seller End</span></a></h3><p>Sellers will see membership options right after signing up.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Screenshot-7-1.png" alt="Membership3"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Screenshot-6-1.png" alt="Membership3"></p><p>If it’s a <strong>Prepaid Plan</strong>, seller chooses and pays via available payment methods:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Choose-Payment-Method-for-Membership-Seller-7.png" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Choose-Payment-Method-for-Membership-Seller-7.png" alt="Membership2"></a></p><hr><h3 id="deactivate-plan-admin-seller" tabindex="-1"><a class="header-anchor" href="#deactivate-plan-admin-seller"><span>Deactivate Plan (Admin &amp; Seller)</span></a></h3><p><strong>Admin Panel:</strong></p><p>Go to <strong>Sellers → Membership Plan → Select Seller → Deactivate</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Screenshot-19-1.png" alt="Screenshot (19)"></p><p><strong>Seller Panel:</strong></p><p>Admin must first enable this from <strong>Membership Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/Screenshot-18-1.png" alt="Screenshot (18)"></p><p>Then seller can do:</p><ul><li>Go to Seller Panel → Profile → Membership Plan</li><li>Click <strong>Deactivate</strong></li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Membership-Plan-Seller-•-Multivendor-MarketPlace-1200x717.png" alt="Membership-Plan-Seller-•-Multivendor-MarketPlace"></p><p>To update card details, click <strong>View → Update Card</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Membership-Plan-Seller-•-Multivendor-MarketPlace-1.png" alt="Membership-Plan-Seller-•-Multivendor-MarketPlace-1"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Membership-Plan-Seller-•-Multivendor-MarketPlace-2.png" alt="Membership-Plan-Seller-•-Multivendor-MarketPlace-2"></p><p>If card is invalid:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-by-Lightshot-3-1-1200x812.png" alt="Screenshot-by-Lightshot-3-1"></p><hr><h3 id="payment-history" tabindex="-1"><a class="header-anchor" href="#payment-history"><span>Payment History</span></a></h3><p>Admin:</p><ul><li>Go to <strong>Sellers → Seller Memberships → Select Seller → Payment History → View</strong></li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/08/screenshot_1690984483943-1200x413.png" alt="screenshot_1690984483943"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/08/screenshot_1690897965199-1200x612.png" alt="screenshot_1690897965199"></p><p>Seller:</p><ul><li>Go to <strong>Profile → Membership Plan</strong></li></ul><hr><h3 id="display-membership-plan-only-to-selected-sellers" tabindex="-1"><a class="header-anchor" href="#display-membership-plan-only-to-selected-sellers"><span>Display Membership Plan Only to Selected Sellers</span></a></h3><p>Enable <strong>Assign to Particular Seller</strong> while creating the plan and enter seller emails.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/04/screenshot_1712319021401-1200x556.webp" alt="image"></p><hr><h3 id="ecpay-payment-method-for-membership" tabindex="-1"><a class="header-anchor" href="#ecpay-payment-method-for-membership"><span>EcPay Payment Method for Membership</span></a></h3><h4 id="how-to-enable-ecpay" tabindex="-1"><a class="header-anchor" href="#how-to-enable-ecpay"><span>How to Enable EcPay:</span></a></h4><ul><li>Go to <strong>Configuration → Membership Payment Details</strong></li><li>Activate EcPay</li><li>Enter Merchant ID, Hash Key, Hash IV</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/activate-ecpay-membership-1200x785.webp" alt="Ecpay activate for memberhisp"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/details-membership-1200x785.webp" alt="ecpay details for membership"></p><h4 id="seller-flow" tabindex="-1"><a class="header-anchor" href="#seller-flow"><span>Seller Flow:</span></a></h4><ol><li>Choose plan → Select EcPay as payment method</li><li>Click <strong>Pay and Proceed</strong></li></ol><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/selcet-ecpay-1200x785.webp" alt="select-ecpay for seller membership feature"></p><ol start="3"><li>Enter payment details on EcPay page → Submit OTP</li></ol><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/ecpay-interface-737x1024.webp" alt="ecpay interface seller membership feature"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/verifictaion-otp-1200x786.webp" alt="Transaction verification seller membership feature"></p><ol start="4"><li>See <strong>Payment Success</strong> message</li></ol><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/payment-succesfull-ecpay-1200x786.webp" alt="Payment succesfull seller membership feature"></p><p><strong>Note:</strong> After payment confirmation, seller is redirected automatically.</p><hr><h3 id="how-to-deactivate-membership" tabindex="-1"><a class="header-anchor" href="#how-to-deactivate-membership"><span>How to Deactivate Membership</span></a></h3><ol><li>Seller Dashboard → Profile → Membership Plan</li><li>Click <strong>Deactivate</strong>, confirm.</li></ol><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/deactivate-memebrship-1200x943.webp" alt="deactivateseller membership feature"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/02/deactivate-membership-confirm-1200x943.webp" alt="Payment succesfull seller membership feature"></p><p>Test with EcPay sandbox:<br> 👉 <a href="https://developers.ecpay.com.tw/?p=22696" target="_blank" rel="noopener noreferrer">EcPay Developer Sandbox</a></p>',109)]))}const p=l(a,[["render",n]]),h=JSON.parse('{"path":"/zenith/Featured-App/Seller%20Add-Ons/SELLER%20MEMBERSHIP.html","title":"SELLER MEMBERSHIP","lang":"en-US","frontmatter":{"title":"SELLER MEMBERSHIP","description":"SELLER MEMBERSHIP","date":"2025-07-29T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Features","slug":"features","link":"#features","children":[]},{"level":3,"title":"Activation","slug":"activation","link":"#activation","children":[]},{"level":3,"title":"Admin End","slug":"admin-end","link":"#admin-end","children":[]},{"level":3,"title":"Accept Card Details Before Trial Period","slug":"accept-card-details-before-trial-period","link":"#accept-card-details-before-trial-period","children":[]},{"level":3,"title":"Create New Plans","slug":"create-new-plans","link":"#create-new-plans","children":[]},{"level":3,"title":"Set Commission on Membership Plans","slug":"set-commission-on-membership-plans","link":"#set-commission-on-membership-plans","children":[]},{"level":3,"title":"Restrict Sellers to Add Staff in Membership Plan","slug":"restrict-sellers-to-add-staff-in-membership-plan","link":"#restrict-sellers-to-add-staff-in-membership-plan","children":[]},{"level":3,"title":"Set One-Time Setup Fee for Sellers","slug":"set-one-time-setup-fee-for-sellers","link":"#set-one-time-setup-fee-for-sellers","children":[]},{"level":3,"title":"Assign Membership Plans to Sellers","slug":"assign-membership-plans-to-sellers","link":"#assign-membership-plans-to-sellers","children":[]},{"level":3,"title":"Payment from Seller","slug":"payment-from-seller","link":"#payment-from-seller","children":[]},{"level":3,"title":"Seller End","slug":"seller-end","link":"#seller-end","children":[]},{"level":3,"title":"Deactivate Plan (Admin & Seller)","slug":"deactivate-plan-admin-seller","link":"#deactivate-plan-admin-seller","children":[]},{"level":3,"title":"Payment History","slug":"payment-history","link":"#payment-history","children":[]},{"level":3,"title":"Display Membership Plan Only to Selected Sellers","slug":"display-membership-plan-only-to-selected-sellers","link":"#display-membership-plan-only-to-selected-sellers","children":[]},{"level":3,"title":"EcPay Payment Method for Membership","slug":"ecpay-payment-method-for-membership","link":"#ecpay-payment-method-for-membership","children":[]},{"level":3,"title":"How to Deactivate Membership","slug":"how-to-deactivate-membership","link":"#how-to-deactivate-membership","children":[]}],"git":{"updatedTime":1754980561000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"37f2314009fee79d29844e3f75421b31d97c7c49","time":1754980561000,"email":"pratik@webkul.com","author":"pratik","message":"add some more doc"}]},"filePathRelative":"zenith/Featured-App/Seller Add-Ons/SELLER MEMBERSHIP.md"}');export{p as comp,h as data};
